using UnscRelay.Core;
using System.Text.Json;
static class WorkspaceChecks{
public static int Run(){int n=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);n++;}void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}throw new Exception("Accepted "+name);}
var primary=new MonitorArea("main",0,0,3440,1400,true);var secondary=new MonitorArea("4k",-3840,0,3840,2120);var original=new WindowArea(-3500,160,1500,900);var saved=WorkspaceGeometry.Capture(secondary,original,true,1);Check(WorkspaceGeometry.Resolve(saved,[primary,secondary]).Bounds==original,"Roundtrip on second monitor at negative coordinates");
var missing=WorkspaceGeometry.Resolve(saved,[primary]);Check(missing.Relocated&&missing.Monitor.Id=="main"&&missing.Bounds.Left>=0,"Missing monitor uses primary");var smaller=WorkspaceGeometry.Resolve(saved,[new("4k",0,0,1024,728)]);Check(smaller.Bounds.Width<=1024&&smaller.Bounds.Height<=728&&smaller.Bounds.Left+smaller.Bounds.Width<=1024,"Resolution changes stay in work area");var tiny=WorkspaceGeometry.Resolve(saved,[new("4k",0,0,600,400)]);Check(tiny.Bounds.Width==600&&tiny.Bounds.Height==400,"Small work area caps minimum size");
var off=WorkspaceGeometry.Capture(primary,new(-999,-999,9999,9999),false,0);Check(off.X==0&&off.Y==0&&off.Width==1&&off.Height==1,"Offscreen capture clamped");Reject(()=>(saved with{X=double.NaN}).Validate(),"NaN rejected");Reject(()=>(saved with{Height=0}).Validate(),"Zero height rejected");Reject(()=>(saved with{Order=10}).Validate(),"Invalid window order rejected");Reject(()=>WorkspaceGeometry.Resolve(saved,[]),"No monitor rejected");
var legacy=JsonSerializer.Deserialize<Workspace>("{\"Name\":\"Old\",\"Layout\":\"columns\",\"ProfileIds\":[\"p\"]}")!;legacy.Validate();Check(legacy.WindowPlacements==null,"Legacy workspace loads");var w=new Workspace("Full","grid",["p","p"],["One","Two"],["session","sftp"],[null,saved],1,[1,0,-1,-1],[.7,.3]);w.Validate();var copy=JsonSerializer.Deserialize<Workspace>(JsonSerializer.Serialize(w))!;copy.Validate();Check(copy.WindowPlacements![1]==saved&&copy.SplitPaneIndices!.SequenceEqual(w.SplitPaneIndices!),"Workspace geometry and slots persist");Reject(()=>(w with{SplitPaneIndices=[0,0]}).Validate(),"Duplicate slot rejected");Reject(()=>(w with{SplitRatios=[.01,.5]}).Validate(),"Unusable ratio rejected");Reject(()=>(w with{WindowPlacements=[saved]}).Validate(),"Misaligned windows rejected");Reject(()=>(w with{ActivePaneIndex=2}).Validate(),"Invalid active tab rejected");Console.WriteLine(n+" workspace checks passed");return 0;}}
